import json,pprint
D=json.load(open('/workspace/contracts/openapi.contract.json'))
for path,item in D['paths'].items():
 for method,o in item.items():
  if method not in ('get','post'): continue
  print('\n###',method.upper(),path,o['operationId'])
  print('params:',[(x['name'],x['in'],x.get('required'),x.get('schema')) for x in o.get('parameters',[])])
  rb=o.get('requestBody'); print('body:', json.dumps(rb.get('content',{}).get('application/json',{}).get('schema')) if rb else '-')
  for code,r in o['responses'].items():
   c=r.get('content',{}).get('application/json',{}); 
   if c: print('resp',code,json.dumps(c.get('schema')))
PY

