cat > /workspace/backend/main.go <<'EOF'
package main

import (
 "crypto/sha256"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "io"
 "log"
 "math"
 "net/http"
 "os"
 "path/filepath"
 "strings"
 "sync"
 "time"
 "github.com/google/uuid"
)

type User struct { ID, Username, Password, Email, FullName, Phone string; Roles, Qualifications []string; Certifications []map[string]any; Active bool; AssignedLocationID string }
type SampleType struct { ID, Name, RequiredQualification, ContainerType string; QualifiedCollectorRequired bool; TempMin, TempMax float64; Incompatible []string; RequiresCooledRoute, BatchingAllowed bool }
type Location struct { ID, Name string; Lat, Lon, CoverageKm float64; HandlingMinutes int; Active bool; Functions map[string]bool; Capacity, Reserved, CooledCapacity, CooledReserved int }
type Connection struct { ID, From, To string; Travel int; Cost float64; Cooled, Active bool; Capacity, Reserved, CooledCapacity, CooledReserved int }
type Sample struct { ID, RequestID, RequesterID, TypeID, OriginType, OriginNodeID, State, HolderID, TargetLabID, JourneyID string; Origin map[string]any; RequestedAt, Deadline, Earliest, Latest, SealedAt, LatestLocationAt string; Container string; TempMin, TempMax float64; Incompatible []string; Exception string; Timeline []map[string]any; ActiveAssignments []string }
type Assignment struct { ID, SampleID, JourneyID, Kind, Status, WorkerID, From, To, NodeID, LabID string; Sequence int; OfferExpiresAt string; History []map[string]any }
type Journey struct { ID string; PlanVersion int; RouteMode, Status string; SampleIDs []string; Stops []map[string]any; Legs []map[string]any; EstimatedDeliveryAt string; TotalCost float64; CapacityUsed, CapacityAvailable int }
type Handoff struct { ID, SampleID, SenderID, ReceiverID, FromAssignmentID, ToAssignmentID, Status string; SenderConfirmed, ReceiverConfirmed bool }
type Audit struct { ID, ActorID, Role, Action, EntityType, EntityID string; Success bool; At string; Details map[string]any }
type State struct { Users map[string]User; SampleTypes map[string]SampleType; Locations map[string]Location; Connections map[string]Connection; Samples map[string]Sample; Assignments map[string]Assignment; Journeys map[string]Journey; Handoffs map[string]Handoff; Audits []Audit; Idempotency map[string]any; Version int; ServiceabilityVersion int }
type Session struct { UserID, Role string }
type Server struct { mu sync.Mutex; state State; sessions map[string]Session; file string }

func now() string { return time.Now().UTC().Format(time.RFC3339Nano) }
func uid() string { return uuid.New().String() }
func hash(s string) string { b:=sha256.Sum256([]byte(s)); return hex.EncodeToString(b[:]) }
func newState() State { return State{Users:map[string]User{},SampleTypes:map[string]SampleType{},Locations:map[string]Location{},Connections:map[string]Connection{},Samples:map[string]Sample{},Assignments:map[string]Assignment{},Journeys:map[string]Journey{},Handoffs:map[string]Handoff{},Idempotency:map[string]any{},Version:1,ServiceabilityVersion:1} }
func (s *Server) load() { b,e:=os.ReadFile(s.file); if e==nil { json.Unmarshal(b,&s.state) }; if s.state.Users==nil { s.state=newState() }; if s.state.SampleTypes==nil {s.state.SampleTypes=map[string]SampleType{}}; s.seed() }
func (s *Server) seed() { if len(s.state.SampleTypes)>0{return}; vals:=[]SampleType{{Name:"Amber",ContainerType:"standard",TempMin:15,TempMax:25,QualifiedCollectorRequired:true,RequiredQualification:"amber",BatchingAllowed:true},{Name:"Indigo",ContainerType:"standard",TempMin:15,TempMax:25,QualifiedCollectorRequired:true,RequiredQualification:"indigo",BatchingAllowed:true},{Name:"Frost",ContainerType:"cooled",TempMin:2,TempMax:8,QualifiedCollectorRequired:true,RequiredQualification:"frost",RequiresCooledRoute:true,BatchingAllowed:true},{Name:"Pulse",ContainerType:"standard",TempMin:15,TempMax:25,QualifiedCollectorRequired:true,RequiredQualification:"pulse",BatchingAllowed:false}}; for _,v:=range vals {v.ID=uid();v.Incompatible=[]string{};s.state.SampleTypes[v.ID]=v} }
func (s *Server) save() { b,_:=json.MarshalIndent(s.state,"","  "); os.MkdirAll(filepath.Dir(s.file),0755); os.WriteFile(s.file,b,0644) }
func (s *Server) audit(actor,role,action,typ,id string, ok bool, details map[string]any) { s.state.Audits=append(s.state.Audits,Audit{uid(),actor,role,action,typ,id,ok,now(),details}) }
func writeJSON(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);json.NewEncoder(w).Encode(v)}
func envelope(v any) map[string]any{return map[string]any{"data":v}}
func errJSON(w http.ResponseWriter,status int,code string){writeJSON(w,status,map[string]string{"error":strings.ReplaceAll(code,"_"," "),"code":code})}
func body(r *http.Request,v any) error { b,e:=io.ReadAll(io.LimitReader(r.Body,2<<20));if e!=nil{return e};if len(b)==0{return fmt.Errorf("empty")};return json.Unmarshal(b,v) }
func (s *Server) auth(r *http.Request) (User,Session,bool) { h:=r.Header.Get("Authorization"); if !strings.HasPrefix(h,"Bearer "){return User{},Session{},false}; s.mu.Lock();defer s.mu.Unlock();ss,ok:=s.sessions[strings.TrimPrefix(h,"Bearer ")];u,ok2:=s.state.Users[ss.UserID];return u,ss,ok&&ok2&&u.Active }
func has(u User, roles ...string) bool { for _,r:=range roles {for _,x:=range u.Roles {if x==r||x=="administrator" {return true}}};return false }
func (s *Server) require(w http.ResponseWriter,r *http.Request,roles ...string)(User,Session,bool){u,ss,ok:=s.auth(r);if !ok{errJSON(w,401,"unauthorized");return u,ss,false};if len(roles)>0&&!has(u,roles...){errJSON(w,403,"forbidden");return u,ss,false};return u,ss,true}
func certOK(u User,t SampleType) bool { if !t.QualifiedCollectorRequired{return true}; for _,q:=range u.Qualifications {if q==t.RequiredQualification{return true}};for _,c:=range u.Certifications {if c["code"]==t.RequiredQualification&&c["active"]!=false{return true}};return false }
func isoOr(v any) string {if x,ok:=v.(string);ok&&x!=""{return x};return now()}
func (s *Server) location(id string) (Location,bool){l,ok:=s.state.Locations[id];return l,ok}
