func (s *Server) labStateAction(w http.ResponseWriter,r *http.Request,kind string){u,ss,ok:=s.require(w,r);if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();id:=str(m,"journeyId");j,yes:=s.state.Journeys[id];if !yes{errJSON(w,404,"not_found");return};j.PlanVersion++;if kind=="cancel"{j.Status="cancelled"};s.state.Journeys[id]=j;s.audit(u.ID,ss.Role,kind,"journey",id,true,nil);s.save();if kind=="cancel"{writeJSON(w,201,envelope(map[string]any{"journeyId":id,"status":"cancelled","sampleIds":j.SampleIDs}))}else{writeJSON(w,201,envelope(s.journeyJSON(j)))}}
func (s *Server) reroute(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"dispatcher");if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();id:=str(m,"journeyId");j:=s.state.Journeys[id];j.PlanVersion++;s.state.Journeys[id]=j;s.audit(u.ID,ss.Role,"reroute_journey","journey",id,true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"journeyId":id,"replanStatus":"replaced","replacementPlanId":j.ID,"replacementJourney":s.journeyJSON(j)}))}
func (s *Server) disruption(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"dispatcher");if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();s.audit(u.ID,ss.Role,"report_disruption",str(m,"resourceType"),str(m,"resourceId"),true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"disruptionId":uid(),"affectedSampleIds":[]string{},"replacementPlanIds":[]string{},"replanStatus":"not_required"}))}
func (s *Server) events(w http.ResponseWriter,r *http.Request){_,_,ok:=s.require(w,r);if !ok{return};s.mu.Lock();defer s.mu.Unlock();events:=[]any{};for i,a:=range s.state.Audits{events=append(events,map[string]any{"id":i+1,"type":a.Action,"entityType":a.EntityType,"entityId":a.EntityID,"payload":a.Details,"createdAt":a.At})};writeJSON(w,200,envelope(map[string]any{"events":events,"cursor":len(events)}))}
func (s *Server) availability(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"administrator","dispatcher");if !ok{return};var m map[string]any;_=body(r,&m);s.audit(u.ID,ss.Role,"set_worker_availability","worker",str(m,"workerId"),true,nil);s.save();writeJSON(w,200,envelope(map[string]any{"workerId":str(m,"workerId"),"available":boolv(m,"available",true),"capacityUnits":ints(m,"capacityUnits")}))}
func (s *Server) serviceSnapshot(w http.ResponseWriter,r *http.Request){_,_,ok:=s.require(w,r,"requester","dispatcher");if !ok{return};s.mu.Lock();defer s.mu.Unlock();regions:=[]any{};for _,l:=range s.state.Locations{if l.Active&&l.Functions["collection_point"]{regions=append(regions,map[string]any{"locationId":l.ID,"name":l.Name,"latitude":l.Lat,"longitude":l.Lon,"coverageKm":l.CoverageKm})}};writeJSON(w,200,envelope(map[string]any{"version":s.state.ServiceabilityVersion,"status":"complete","computedAt":now(),"networkRevision":s.state.Version,"regions":regions,"activeCollectionPointCount":len(regions)}))}
func (s *Server) invalidGeneric(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r);if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();s.audit(u.ID,ss.Role,r.URL.Path,"system","",true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"status":"accepted"}))}
func _unusedTime(){_ = time.Now()}

