 if r.URL.Path=="/api/set-location-status"&&r.Method=="POST"{s.locationStatus(w,r,false);return}
 if r.URL.Path=="/api/set-location-function-status"&&r.Method=="POST"{s.locationStatus(w,r,true);return}
 if r.URL.Path=="/api/create-connection"&&r.Method=="POST"{s.connection(w,r,true);return}
 if r.URL.Path=="/api/set-connection-status"&&r.Method=="POST"{s.connection(w,r,false);return}
 if r.URL.Path=="/api/create-sample-type"&&r.Method=="POST"{s.sampleType(w,r,true);return}
 if r.URL.Path=="/api/update-sample-type"&&r.Method=="POST"{s.sampleType(w,r,false);return}
 if r.URL.Path=="/api/configure-capacity"&&r.Method=="POST"{s.capacity(w,r);return}
 if r.URL.Path=="/api/configure-laboratory-acceptance"&&r.Method=="POST"{s.labAcceptance(w,r);return}
 if r.URL.Path=="/api/configure-capacity"&&r.Method=="POST"{s.capacity(w,r);return}
 if r.URL.Path=="/api/record-handling-checkpoint"&&r.Method=="POST"{s.checkpoint(w,r);return}
 if r.URL.Path=="/api/initiate-handoff"&&r.Method=="POST"{s.initiateHandoff(w,r);return}
 if r.URL.Path=="/api/confirm-handoff"&&r.Method=="POST"{s.confirmHandoff(w,r);return}
 if r.URL.Path=="/api/confirm-laboratory-receipt"&&r.Method=="POST"{s.receipt(w,r);return}
 if r.URL.Path=="/api/record-laboratory-exception"&&r.Method=="POST"{s.labException(w,r);return}
 if r.URL.Path=="/api/record-worker-location"&&r.Method=="POST"{s.workerLocation(w,r);return}
 if r.URL.Path=="/api/set-worker-availability"&&r.Method=="POST"{s.availability(w,r);return}
 if r.URL.Path=="/api/cancel-journey"&&r.Method=="POST"{s.labStateAction(w,r,"cancel");return}
 if r.URL.Path=="/api/reroute-journey"&&r.Method=="POST"{s.reroute(w,r);return}
 if r.URL.Path=="/api/report-disruption"&&r.Method=="POST"{s.disruption(w,r);return}
 if r.URL.Path=="/api/edit-active-plan"&&r.Method=="POST"{s.labStateAction(w,r,"edit_active_plan");return}
 if r.URL.Path=="/api/merge-journeys"&&r.Method=="POST"{s.labStateAction(w,r,"merge_journeys");return}
 if r.URL.Path=="/api/split-journey"&&r.Method=="POST"{s.labStateAction(w,r,"split_journey");return}
 if r.URL.Path=="/api/invalid"{s.invalidGeneric(w,r);return}
 errJSON(w,404,"not_found")
}
func ensureAdmin(s *Server){s.mu.Lock();defer s.mu.Unlock();for _,u:=range s.state.Users{if u.Roles!=nil{return}};username:=os.Getenv("ADMIN_USERNAME");password:=os.Getenv("ADMIN_PASSWORD");if username==""{username="admin"};if password==""{password="admin"};id:=uid();s.state.Users[id]=User{ID:id,Username:username,Password:hash(password),FullName:"System Administrator",Roles:[]string{"administrator"},Active:true};s.save()}
func main(){f:=os.Getenv("APP_DATA_FILE");if f==""{f=filepath.Join("data","state.json")};s:=&Server{file:f,sessions:map[string]Session{}};s.load();ensureAdmin(s);mux:=http.NewServeMux();mux.HandleFunc("/",s.route);port:=os.Getenv("PORT");if port==""{port="8080"};log.Printf("lab logistics listening on 127.0.0.1:%s",port);if err:=http.ListenAndServe("127.0.0.1:"+port,mux);err!=nil{log.Fatal(err)}}

