import React, {useEffect, useState} from 'react';
import {createRoot} from 'react-dom/client';
import './style.css';

type Any = Record<string, any>;
const api = async (path:string, options:RequestInit={}) => { const token=localStorage.getItem('sessionToken'); const headers:any={'Content-Type':'application/json',...(options.headers||{})}; if(token)headers.Authorization=`Bearer ${token}`; const res=await fetch(path,{...options,headers}); const data=await res.json().catch(()=>({})); if(!res.ok)throw new Error(data.error||data.code||'Request failed'); return data.data??data; };
const post=(p:string,b:Any={})=>api(p,{method:'POST',body:JSON.stringify(b)});
const fmt=(v:any)=>v?new Date(v).toLocaleString(): '—';
