package main

import (
	"log"
	"net/http"
	"os"
	"path/filepath"
)

func (s *Server) route(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path == "/ready" {
		writeJSON(w, 200, map[string]string{"status": "ready"})
		return
	}
	if r.URL.Path == "/api/authenticate-user" && r.Method == "POST" {
		s.authHandler(w, r)
		return
	}
	if r.URL.Path == "/api/ui/bootstrap" && r.Method == "GET" {
		s.bootstrap(w, r)
		return
	}
	if r.URL.Path == "/api/select-active-role" && r.Method == "POST" {
		s.selectRole(w, r)
		return
	}
	if r.URL.Path == "/api/check-serviceability" && r.Method == "POST" {
		s.checkService(w, r)
		return
	}
	if r.URL.Path == "/api/create-collection-request" && r.Method == "POST" {
		s.createRequest(w, r, false)
		return
	}
	if r.URL.Path == "/api/ingest-presealed-sample" && r.Method == "POST" {
		s.createRequest(w, r, true)
		return
	}
	if r.URL.Path == "/api/list-role-work" && r.Method == "POST" {
		s.listWork(w, r)
		return
	}
	if r.URL.Path == "/api/accept-assignment" && r.Method == "POST" {
		s.accept(w, r, true)
		return
	}
	if r.URL.Path == "/api/decline-assignment" && r.Method == "POST" {
		s.accept(w, r, false)
		return
	}
	if r.URL.Path == "/api/collect-and-seal-sample" && r.Method == "POST" {
		s.seal(w, r)
		return
	}
	if r.URL.Path == "/api/update-assignment-progress" && r.Method == "POST" {
		s.updateProgress(w, r)
		return
	}
	if r.URL.Path == "/api/read-sample-state/" {
		s.sampleRead(w, r, false)
		return
	}
	if len(r.URL.Path) > 24 && r.URL.Path[:24] == "/api/read-sample-state/" && r.Method == "GET" {
		s.sampleRead(w, r, false)
		return
	}
	if r.URL.Path == "/api/read-sample-lifecycle" && r.Method == "POST" {
		s.sampleRead(w, r, true)
		return
	}
	if r.URL.Path == "/api/read-journey-plan" && r.Method == "POST" {
		s.readJourney(w, r)
		return
	}
	if r.URL.Path == "/api/read-operations-state" && r.Method == "POST" {
		s.readOperations(w, r)
		return
	}
	if r.URL.Path == "/api/read-serviceability-snapshot" && r.Method == "POST" {
		s.serviceSnapshot(w, r)
		return
	}
	if r.URL.Path == "/api/search-audit-trail" && r.Method == "POST" {
		s.auditSearch(w, r)
		return
	}
	if r.URL.Path == "/api/events" && r.Method == "GET" {
		s.events(w, r)
		return
	}
	if r.URL.Path == "/api/create-user" && r.Method == "POST" {
		s.createUser(w, r)
		return
	}
	if len(r.URL.Path) > 16 && r.URL.Path[:16] == "/api/read-user/" && r.Method == "GET" {
		s.readUser(w, r)
		return
	}
	if r.URL.Path == "/api/update-user-access" && r.Method == "POST" {
		s.updateAccess(w, r)
		return
	}
	if r.URL.Path == "/api/create-location" && r.Method == "POST" {
		s.locationCreate(w, r, false)
		return
	}
	if r.URL.Path == "/api/update-location" && r.Method == "POST" {
		s.locationCreate(w, r, true)
		return
	}
	if r.URL.Path == "/api/set-location-status" && r.Method == "POST" {
		s.locationStatus(w, r, false)
		return
	}
	if r.URL.Path == "/api/set-location-function-status" && r.Method == "POST" {
		s.locationStatus(w, r, true)
		return
	}
	if r.URL.Path == "/api/create-connection" && r.Method == "POST" {
		s.connection(w, r, true)
		return
	}
	if r.URL.Path == "/api/set-connection-status" && r.Method == "POST" {
		s.connection(w, r, false)
		return
	}
	if r.URL.Path == "/api/create-sample-type" && r.Method == "POST" {
		s.sampleType(w, r, true)
		return
	}
	if r.URL.Path == "/api/update-sample-type" && r.Method == "POST" {
		s.sampleType(w, r, false)
		return
	}
	if r.URL.Path == "/api/configure-capacity" && r.Method == "POST" {
		s.capacity(w, r)
		return
	}
	if r.URL.Path == "/api/configure-laboratory-acceptance" && r.Method == "POST" {
		s.labAcceptance(w, r)
		return
	}
	if r.URL.Path == "/api/configure-capacity" && r.Method == "POST" {
		s.capacity(w, r)
		return
	}
	if r.URL.Path == "/api/record-handling-checkpoint" && r.Method == "POST" {
		s.checkpoint(w, r)
		return
	}
	if r.URL.Path == "/api/initiate-handoff" && r.Method == "POST" {
		s.initiateHandoff(w, r)
		return
	}
	if r.URL.Path == "/api/confirm-handoff" && r.Method == "POST" {
		s.confirmHandoff(w, r)
		return
	}
	if r.URL.Path == "/api/confirm-laboratory-receipt" && r.Method == "POST" {
		s.receipt(w, r)
		return
	}
	if r.URL.Path == "/api/record-laboratory-exception" && r.Method == "POST" {
		s.labException(w, r)
		return
	}
	if r.URL.Path == "/api/record-worker-location" && r.Method == "POST" {
		s.workerLocation(w, r)
		return
	}
	if r.URL.Path == "/api/set-worker-availability" && r.Method == "POST" {
		s.availability(w, r)
		return
	}
	if r.URL.Path == "/api/cancel-journey" && r.Method == "POST" {
		s.labStateAction(w, r, "cancel")
		return
	}
	if r.URL.Path == "/api/reroute-journey" && r.Method == "POST" {
		s.reroute(w, r)
		return
	}
	if r.URL.Path == "/api/report-disruption" && r.Method == "POST" {
		s.disruption(w, r)
		return
	}
	if r.URL.Path == "/api/edit-active-plan" && r.Method == "POST" {
		s.labStateAction(w, r, "edit_active_plan")
		return
	}
	if r.URL.Path == "/api/merge-journeys" && r.Method == "POST" {
		s.labStateAction(w, r, "merge_journeys")
		return
	}
	if r.URL.Path == "/api/split-journey" && r.Method == "POST" {
		s.labStateAction(w, r, "split_journey")
		return
	}
	if r.URL.Path == "/api/invalid" {
		s.invalidGeneric(w, r)
		return
	}
	errJSON(w, 404, "not_found")
}
func ensureAdmin(s *Server) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, u := range s.state.Users {
		if u.Roles != nil {
			return
		}
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	id := uid()
	s.state.Users[id] = User{ID: id, Username: username, Password: hash(password), FullName: "System Administrator", Roles: []string{"administrator"}, Active: true}
	s.save()
}
func main() {
	f := os.Getenv("APP_DATA_FILE")
	if f == "" {
		f = filepath.Join("data", "state.json")
	}
	s := &Server{file: f, sessions: map[string]Session{}}
	s.load()
	ensureAdmin(s)
	mux := http.NewServeMux()
	mux.HandleFunc("/", s.route)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("lab logistics listening on 127.0.0.1:%s", port)
	if err := http.ListenAndServe("127.0.0.1:"+port, mux); err != nil {
		log.Fatal(err)
	}
}

